effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
#define _SourceTex_TexelSize (1.0 / vec2(textureSize(inputImg, 0)))
vec4 u_xlat0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat8;
float u_xlat9;
bool u_xlatb9;
vec2 u_xlat13;
bvec2 u_xlatb13;
float u_xlat14;
float u_xlat18;
float u_xlat20;
bool u_xlatb20;
void main()
{
    u_xlat0.xyz = _color.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat0.xyz = _color.xyz * u_xlat0.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat0.xyz = u_xlat0.xyz * _color.xyz;
    u_xlat1.xyw = acScreenNorm.xyy + vec3(-0.5, -0.5, -0.5);
    u_xlat1.xy = u_xlat1.xy / _SourceTex_TexelSize.xy;
    u_xlat18 = _resolution.x / _resolution.y;
    u_xlat2.x = u_xlat18 * 0.5;
    u_xlat1.z = acScreenNorm.x * u_xlat18 + (-u_xlat2.x);
    u_xlat18 = dot(u_xlat1.zw, u_xlat1.zw);
    u_xlat2.x = inversesqrt(u_xlat18);
    u_xlat13.xy = u_xlat1.zw * u_xlat2.xx;
    u_xlat2.x = float(int(_iteration));
    u_xlat18 = _intensity / u_xlat18;
    u_xlat8 = float(0.0);
    u_xlat14 = float(1.0);
    while(true){
        u_xlatb20 = u_xlat14>=u_xlat2.x;
        if(u_xlatb20){break;}
        u_xlat20 = u_xlat14 * _cur_time;
        u_xlat20 = u_xlat20 * _frequency;
        u_xlat20 = u_xlat20 * 0.300000012;
        u_xlat20 = sin(u_xlat20);
        u_xlat20 = u_xlat20 * 0.5 + 0.5;
        u_xlat20 = u_xlat18 * u_xlat20;
        u_xlat3.x = u_xlat14 * 10.0;
        u_xlat3.x = _cur_time * _speed + (-u_xlat3.x);
        u_xlat3.x = u_xlat3.x * 0.25;
        u_xlat4.x = cos(u_xlat3.x);
        u_xlat3.x = sin(u_xlat3.x);
        u_xlat4.y = u_xlat3.x;
        u_xlat3.x = dot(u_xlat4.xy, u_xlat13.xy);
        u_xlat3.x = abs(u_xlat3.x) * abs(u_xlat3.x);
        u_xlat3.x = u_xlat3.x * u_xlat3.x;
        u_xlatb9 = _threshold<u_xlat3.x;
        u_xlat9 = u_xlatb9 ? 1.0 : float(0.0);
        u_xlat3.x = u_xlat9 * u_xlat3.x;
        u_xlat20 = u_xlat20 * u_xlat3.x;
        u_xlat20 = u_xlat20 * 0.925000012;
        u_xlat20 = u_xlat20 / u_xlat14;
        u_xlat8 = u_xlat20 + u_xlat8;
        u_xlat14 = u_xlat14 + 1.0;
    }
    u_xlatb13.xy = equal(ivec4(int(_pattern), int(_blend_mode), int(_pattern), int(_blend_mode)), ivec4(1, 1, 1, 1)).xy;
    u_xlat18 = u_xlat1.x * u_xlat1.y;
    u_xlat18 = u_xlat18 * 0.666666687;
    u_xlatb1.x = u_xlat18>=(-u_xlat18);
    u_xlat18 = fract(abs(u_xlat18));
    u_xlat18 = (u_xlatb1.x) ? u_xlat18 : (-u_xlat18);
    u_xlat18 = u_xlat18 * 15.0;
    u_xlat18 = sin(u_xlat18);
    u_xlat18 = abs(u_xlat18) + 1.0;
    u_xlat18 = (u_xlatb13.x) ? u_xlat18 : 1.0;
    u_xlat18 = u_xlat8 * u_xlat18;
    u_xlat2.xyz = u_xlat0.xyz * vec3(u_xlat18);
    u_xlat2.w = u_xlat18 * _color.w;
    u_xlat3 = texture(inputImg, acScreenNorm.xy);
    u_xlat4 = u_xlat2 * u_xlat3;
    u_xlat0.xyz = vec3(u_xlat18) * u_xlat0.xyz + u_xlat3.xyz;
    u_xlat0.w = u_xlat3.w;
    u_xlat0 = (u_xlatb13.y) ? u_xlat4 : u_xlat0;
    u_xlat4.xyz = u_xlat2.xyz;
    u_xlat0 = (int(_blend_mode) != 0) ? u_xlat0 : u_xlat4;
    if(int(_use_inner_mask) != 0) {
        u_xlatb1.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat2 = (u_xlatb1.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat3 = u_xlat3 * u_xlat5;
        u_xlat2 = u_xlat2 * u_xlat4 + u_xlat3;
        u_xlat1.x = u_xlat4.x * u_xlat2.w;
        fragColor.w = (u_xlatb1.y) ? u_xlat1.x : u_xlat2.w;
        fragColor.xyz = u_xlat2.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
